static void dump(FILE*f,float*d,int n,cudaStream_t s){std::vector<float>h(n);cudaMemcpyAsync(h.data(),d,n*4,cudaMemcpyDeviceToHost,s);cudaStreamSynchronize(s);fwrite(h.data(),4,n,f);}
int wmain(int argc,wchar_t**argv){if(argc!=3)return 2;insignia::ModelFile m(argv[1]);insignia::DecodeWorkspace x(16);insignia::Qwen35Weights w(m,2ull<<30,x.stream);w.embed(42,x.hidden);insignia::Qwen35Decode d(w,x);for(int l=0;l<3;l++)d.layer(l);FILE*f=_wfopen(argv[2],L"wb");dump(f,x.hidden,4096,x.stream);auto mat=[&](const std::string&base,float*in,float*out){auto z=w.matrix(base);insignia::mxfp4_gemv_v2((const uint32_t*)z.weight.data,(const uint8_t*)z.scales.data,in,out,z.rows,z.cols,x.stream);w.release(base);};std::string p="language_model.model.layers.3",a=p+".self_attn";auto iw=w.storage().acquire(p+".input_layernorm.weight");insignia::rmsnorm_bf16(x.hidden,(uint16_t*)iw.data,x.norm,1,4096,false,x.stream);w.storage().release(p+".input_layernorm.weight");dump(f,x.norm,4096,x.stream);mat(a+".q_proj",x.norm,x.gate);insignia::split_q_gate(x.gate,x.qkv,x.attn_gate,x.stream);mat(a+".k_proj",x.norm,x.key);mat(a+".v_proj",x.norm,x.value);dump(f,x.qkv,4096,x.stream);dump(f,x.attn_gate,4096,x.stream);dump(f,x.key,1024,x.stream);dump(f,x.value,1024,x.stream);auto qw=w.storage().acquire(a+".q_norm.weight"),kw=w.storage().acquire(a+".k_norm.weight");insignia::qwen35_qk_norm_rope_gate(x.qkv,x.key,(uint16_t*)qw.data,(uint16_t*)kw.data,x.attn_gate,x.pos_dev,0,x.stream);dump(f,x.qkv,4096,x.stream);dump(f,x.attn_gate,4096,x.stream);dump(f,x.key,1024,x.stream);insignia::store_kv(x.key,x.value,x.kv_keys,x.kv_values,x.pos_dev,0,x.stream);insignia::gqa_decode(x.qkv,x.kv_keys,x.kv_values,x.core,x.pos_dev,0,16,x.stream);dump(f,x.core,4096,x.stream);insignia::expand_gate_heads(x.attn_gate,x.qkv,x.stream);dump(f,x.qkv,4096,x.stream);insignia::sigmoid_mul(x.core,x.qkv,4096,x.stream);dump(f,x.core,4096,x.stream);mat(a+".o_proj",x.core,x.down);dump(f,x.down,4096,x.stream);insignia::residual_add(x.hidden,x.down,4096,x.stream);dump(f,x.hidden,4096,x.stream);auto post=w.storage().acquire(p+".post_attention_layernorm.weight");insignia::rmsnorm_bf16(x.hidden,(uint16_t*)post.data,x.norm,1,4096,false,x.stream);dump(f,x.norm,4096,x.stream);w.storage().release(p+".post_attention_layernorm.weight");mat(p+".mlp.gate_proj",x.norm,x.gate);mat(p+".mlp.up_proj",x.norm,x.up);dump(f,x.gate,12288,x.stream);dump(f,x.up,12288,x.stream);insignia::silu_mul(x.gate,x.up,x.gate,12288,x.stream);mat(p+".mlp.down_proj",x.gate,x.down);dump(f,x.down,4096,x.stream);insignia::residual_add(x.hidden,x.down,4096,x.stream);dump(f,x.hidden,4096,x.stream);fclose(f);return 0;}
